"""Vote importers and validation (plan 6.4). Votes are never generated by the model."""
from __future__ import annotations

import csv
import re
from pathlib import Path

VALID = {"Y", "N", "A", "NV"}

_ALIASES = {"yes": "Y", "y": "Y", "in favour": "Y", "in favor": "Y", "for": "Y",
            "no": "N", "n": "N", "against": "N", "abstain": "A", "abstains": "A",
            "abstaining": "A", "abstained": "A", "abstention": "A", "abstentions": "A",
            "a": "A", "absent": "NV", "did not vote": "NV", "not voting": "NV",
            "nv": "NV"}


def normalize_vote(value: str) -> str | None:
    key = (value or "").strip().lower()
    if key.upper() in VALID:
        return key.upper()
    return _ALIASES.get(key)


def add_vote(conn, doc_id: int, iso3: str, vote: str, source: str = "manual") -> bool:
    vote = normalize_vote(vote)
    if not vote or not iso3:
        return False
    conn.execute("DELETE FROM votes WHERE doc_id = ? AND iso3 = ?", (doc_id, iso3))
    conn.execute("INSERT INTO votes(doc_id, iso3, vote, source) VALUES (?, ?, ?, ?)",
                 (doc_id, iso3, vote, source))
    return True


def import_csv(conn, path: str | Path) -> dict:
    """CSV columns: symbol,iso3,vote (header optional). Returns a plain summary."""
    path = Path(path)
    added, skipped, missing = 0, 0, []
    with path.open(newline="", encoding="utf-8-sig") as fh:
        reader = csv.reader(fh)
        for row in reader:
            if not row or len(row) < 3:
                continue
            symbol, iso3, vote = row[0].strip(), row[1].strip().upper(), row[2].strip()
            if symbol.lower() in ("symbol", "resolution"):
                continue
            doc = conn.execute("SELECT id FROM documents WHERE symbol = ?", (symbol,)).fetchone()
            if not doc:
                missing.append(symbol)
                continue
            if add_vote(conn, doc["id"], iso3, vote, "undl_csv"):
                added += 1
            else:
                skipped += 1
    conn.commit()
    return {"added": added, "skipped": skipped, "unknown_symbols": sorted(set(missing))}


def tally(conn, doc_id: int) -> dict:
    rows = conn.execute("SELECT vote, COUNT(*) AS n FROM votes WHERE doc_id = ? GROUP BY vote",
                        (doc_id,)).fetchall()
    counts = {row["vote"]: row["n"] for row in rows}
    return {
        "in_favour": counts.get("Y", 0),
        "against": counts.get("N", 0),
        "abstentions": counts.get("A", 0),
        "non_voting": counts.get("NV", 0),
        "total": sum(counts.values()),
    }


def validate(conn, doc_id: int, stated: dict) -> dict:
    """Compare the stored rows with a tally stated in the document text."""
    counted = tally(conn, doc_id)
    mismatches = []
    for key in ("in_favour", "against", "abstentions"):
        if stated.get(key) is not None and stated[key] != counted.get(key, 0):
            mismatches.append(f"{key}: document says {stated[key]}, table has {counted.get(key, 0)}")
    return {"ok": not mismatches, "mismatches": mismatches, "counted": counted}


def members_for(conn, doc_id: int) -> list[dict]:
    rows = conn.execute(
        "SELECT v.iso3, v.vote, COALESCE(c.name, v.iso3) AS name, v.source "
        "FROM votes v LEFT JOIN countries c ON c.iso3 = v.iso3 "
        "WHERE v.doc_id = ? ORDER BY v.vote, name", (doc_id,)).fetchall()
    return [dict(row) for row in rows]


def votes_for_country(conn, iso3: str, topic_id: int | None = None) -> list[dict]:
    sql = (
        "SELECT v.vote, d.symbol, d.title, d.date, d.id AS doc_id "
        "FROM votes v JOIN documents d ON d.id = v.doc_id "
        "WHERE v.iso3 = ?"
    )
    params: list = [iso3]
    if topic_id:
        sql += " AND d.id IN (SELECT doc_id FROM doc_topics WHERE topic_id = ?)"
        params.append(topic_id)
    sql += " ORDER BY d.date"
    return [dict(row) for row in conn.execute(sql, params).fetchall()]


VOTE_PARAGRAPH = re.compile(
    r"(?P<count>\d{1,3})\s+votes?\s+in\s+favour[^.]{0,60}?(?P<against>\d{1,3})\s+against"
    r"(?:[^.]{0,60}?(?P<abs>\d{1,3})\s+abstentions?)?",
    re.I,
)
BY_NAME = re.compile(r"(?P<name>[A-Z][A-Za-z .'\-]{2,40}?)\s*\((?P<vote>yes|no|abstaining|abstained)\)",
                     re.I)


def parse_paragraph(text: str) -> list[dict]:
    """Parse per-country vote notes like 'France (yes), Russia (abstaining)'."""
    return [{"name": m.group("name").strip(), "vote": normalize_vote(m.group("vote"))}
            for m in BY_NAME.finditer(text or "")]
